import json
for fn in ('batch.input.jsonl','description-review-input.json','book-model.json','native-national-scope.json','prerequisite-context.json','memory-cards.json','positive-profiles.json'):
 with open(fn) as f: d=json.loads(next(f)) if fn.endswith('jsonl') else json.load(f)
 def show(d,indent=' '):
  if isinstance(d,dict):
   for k,v in d.items(): print(indent,k, type(v).__name__, len(v) if isinstance(v,(dict,list)) else '', str((next(iter(v),'')) if isinstance(v,dict) else (v[0].keys() if v and isinstance(v[0],dict) else '') if isinstance(v,list) else str(v)[:90]))
  elif isinstance(d,list): print(len(d));show(d[0])
 print(fn);show(d)
PY"

