/bin/bash -lc "python - <<'PY'
import json
c={x['id']:x for x in json.load(open('prerequisite-context.json'))}
g=json.load(open('description-review-input.json'))['goals']
for e in g:
 print('\\n',e['currentTitleEn'])
 for k in e['canonicalContext']['requires']:
  x=c[k];print(x['title'],x['description'],x['descriptionEn'])
 print('prerequisite closure',end=' '); seen=set()
 def walk(k):
  if k in seen:return
  seen.add(k)
  if k in c:
   for a in c[k]['requires']:walk(a)
 for k in e['canonicalContext']['requires']:walk(k)
 print(' > '.join(sorted([c[k]['titleEn'] for k in seen if k in c])))
PY"

